// Code generated from the Python ais by a one-off script; edit freely.
// These are the texts ais prints or writes, kept word for word from the
// Python version so the port changes nothing anyone reads.

package ais

const usageText = "usage: ais run <profile> [options] [-- profile args...]\n       ais [options] -- <profile> [profile args...]\n       ais <command> [options]\n\nrun:\n  ais run claude                    start claude in a tracked session\n  ais -- claude                     ...the same, abbreviated\n  ais run pi                        ...or pi, or any profile in config.toml\n  ais run claude -w -d \"fix the auth bug\" -- --model opus\n  -d, --description TEXT             what this session is for; shown by select\n  -w, --worktree                     make a git worktree of the repo you are in\n                                     at <base>/<session name>/<repo>, on a\n                                     branch of that name, and start the profile\n                                     there. Fails if this is not a repo.\n      --no-worktree                  run here, even with worktree.auto on\n      --from auto|origin|local|head  what the worktree starts from (default:\n                                     worktree.from, which defaults to auto)\n      --[no-]detach                  a detached worktree, no branch (default:\n                                     worktree.detach, which defaults to off)\n      --cwd DIR                      start in DIR rather than here\n      --fork ID                      start a copy of session ID beside it: same\n                                     profile, directory and worktree, with its\n                                     conversation forked (needs session.fork)\n      --prompt TEXT                  the first message for the harness; the\n                                     session stays interactive. Profiles say how\n                                     with prompt = [...] (claude and pi know)\n      --prompt-file PATH             the same, read from PATH (- for stdin)\n      --repos A,B,...                a worktree of each repo, side by side under\n                                     <base>/<session name>/, which the session\n                                     starts in; repeatable\n  -n, --dry-run                      print the command and env, run nothing\n\n  A profile is a named way to start a process — command, flags, env and, for\n  agent harnesses, how to resume a conversation — under [profile.<name>] in\n  config.toml. [harness.<name>] is the old spelling and still works.\n\ncommands:\n  select [id]      pick an active session and switch tmux to its pane;\n                   sessions that notified recently are listed first, marked ●\n                   --client NAME moves that client rather than the one tmux\n                   infers; only needed where tmux cannot infer it.\n  ls [-a]          list active sessions (-a: dead ones too), with the age of\n                   each one's last notification\n  status [-a]      ls plus the recent notifications themselves\n  notify TEXT      raise a desktop notification for this session and record it.\n                   Skipped, but still recorded, while this session's own pane is\n                   the one on screen; -f/--force sends anyway.\n                   -t/--title TEXT overrides the banner title,\n                   --tag TEXT the session label in it, -q/--quiet the chatter.\n  current          show the session this shell is running in\n  name [--set N]   print this session's base name, for worktrees and branches;\n                   derived from the description once, then stable for the\n                   session's whole life. --set overrides it. --of TEXT prints\n                   the name a session described as TEXT would get.\n  restart [id]     run a dead session's harness again in this pane, resuming\n                   its conversation; with no id, the last one that died here.\n                   Keeps its directory and name, gets a new ais id.\n                   --fresh starts a new conversation, -n/--dry-run shows the\n                   command without running it.\n  install          wire a harness up: session flags in config.toml so restart\n                   can resume it, whatever that harness needs in order to report\n                   the conversation it is in — a SessionStart hook in\n                   ~/.claude/settings.json for claude, a session_start extension\n                   in ~/.pi/agent/extensions/ais.ts for pi — and a section in its\n                   global instructions (~/.claude/CLAUDE.md, ~/.pi/agent/AGENTS.md)\n                   telling the agent how to use ais from inside a session.\n                   --harness claude|pi (default claude), -n/--dry-run,\n                   --force to rewrite wiring ais did not write itself.\n  instructions [H] print the ais section of a harness's global instructions\n                   (claude or pi, default claude) instead of writing it, for a\n                   setup that assembles those files itself and must not keep a\n                   second copy of the text. --markers wraps it in the\n                   <!-- ais:begin --> … <!-- ais:end --> markers install uses.\n  state            every profile and session as JSON, for other programs (tsm):\n                   what is running, where its pane is now, what can be\n                   restarted, resumed or forked, and its notifications.\n                   --active drops dead sessions; --since ID keeps only\n                   notifications newer than ID. Versioned by its \"api\" key.\n  env <id>         where a session runs and the env a shell beside it needs:\n                   shell to eval, or --json. Includes AIS_SESSION, with\n                   AIS_SIBLING=1 to mark the shell as not the agent.\n  flow <cmd>       planned and dispatched sessions: workspaces, a queue of the\n                   sessions you accepted, limits; ais flow --help\n  wt <cmd>         worktrees for this session, all under one directory:\n                     add [repo]   worktree of repo (default: here) at\n                                  <base>/<session name>/<repo>; prints the path.\n                                  Takes --from and --[no-]detach, as -w does.\n                     ls [-a]      this session's worktrees (-a: every session's)\n                     path [repo]  print one path, for cd\n                     prune        drop registrations git holds for worktrees\n                                  that are already gone\n  prune [--all]    drop dead sessions older than --days (default 7), and the\n                   worktrees of the ones it drops — but never a worktree with\n                   uncommitted changes or unpushed commits, and never one a\n                   surviving session is still standing in.\n                   --keep-worktrees leaves every directory alone.\n\nworktrees:\n  A session's worktrees live at <base>/<session name>/<repo>, where <base> is\n  worktree.base in config.toml (~/wt by default, $AIS_WT_BASE overrides) and\n  <session name> is \"ais name\". The branch is that name too, in every repo, so\n  the directory, the branch and the session all agree. A session started with\n  -w exports AIS_WORKTREE, AIS_WORKTREE_BASE and AIS_REPO_MAIN (the main\n  checkout the worktree branched from) for the agent to find them.\n\n  auto = true under [worktree] makes that the default: every session gets a\n  worktree when you start it inside a repo, and runs where you are when you do\n  not. Only a -w you typed yourself insists — that one fails outside a repo.\n\n  A new branch starts where worktree.from says (--from overrides it):\n    origin  the remote's default branch, e.g. origin/main, after a fetch\n    local   that branch as the main checkout has it, e.g. main\n    head    whatever commit the main checkout has out right now\n    auto    origin, unless local holds commits origin does not have yet: then\n            local. If the two have diverged, origin, with a warning. (default)\n  detach = true (or --detach) gives the worktree that commit and no branch.\n  A branch of the session's name that already exists is reused as it is.\n\ntmux:\n  A session renames its window after itself while it runs — the session name,\n  else the profile — and puts the old name back when it ends; otherwise tmux\n  names every window after the process it sees, which is ais, which is Python.\n  Turn it off with rename = false under [tmux] in config.toml.\n\n  It also marks its pane with @ais_id, @ais_profile, @ais_desc and @cwd while\n  it runs, and stands in the session's directory itself, so #{pane_current_path}\n  — and every split made with -c \"#{pane_current_path}\" — lands in the agent's\n  worktree rather than wherever ais was started.\n\n  bind-key a display-popup -E -w 80% -h 60% -T \" ais \" \\\n    \"{self} select\"\n\n  Picking from that popup switches the client underneath it and the popup\n  closes on its own, leaving you in the chosen session's pane. Do not pass\n  --client '#{client_name}': display-popup hands its command to the shell\n  unexpanded, so the format arrives literally. select works it out itself.\n\nfiles:\n  {config}      per-harness flags and env, [worktree], [tmux], [notify]\n  {sessions}    session state\n\nais must run inside tmux: a session it cannot jump back to is not worth tracking.\n"

const defaultConfig = "# ais configuration.\n#\n# A profile is a named way to start a process: its command, flags, env and,\n# for agent harnesses, how it names conversations. [defaults] applies to every\n# profile; [profile.<name>] adds to it. The name is the token you type after\n# \"ais run\" or \"--\" (its basename if you pass a path), so \"ais run claude\" and\n# \"ais -- claude\" both read [profile.claude]. A name with a dot in it has to be\n# quoted: [profile.\"my-agent.sh\"]. [harness.<name>] is the old spelling and is\n# still read; where both exist, [profile.<name>] wins key by key.\n#\n# Final argv is:   <command> <config flags> <args you typed after the profile>\n# Yours come last so the same flag typed by hand overrides the config default.\n#\n# env values go through ~ and $VAR expansion.\n\n[defaults]\nflags = []\n\n[defaults.env]\n# MY_SHARED_VAR = \"value\"\n\n[profile.claude]\nflags = []\n# command = [\"claude\"]   # override the executable, e.g. [\"npx\", \"claude\"]\n\n[profile.claude.env]\n# ANTHROPIC_LOG = \"debug\"\n\n# [profile.<name>.session] teaches ais how that harness names conversations, so\n# \"ais restart\" can pick one up where it left off. {id} is the conversation id:\n# ais mints it (see \"id\") for a new session and replays it for a restart.\n# Without this table a profile is still tracked, it just restarts fresh.\n#\n# [profile.claude.session]\n# id = \"uuid4\"                     # or \"short\" for ais's own id alphabet\n# new = [\"--session-id\", \"{id}\"]\n# resume = [\"--resume\", \"{id}\"]\n# fork = [\"--resume\", \"{id}\", \"--fork-session\"]   # \"ais run --fork\": a copy\n# conflicts = [\"-c\", \"--continue\", \"--fork-session\"]   # you typed it: ais keeps out\n\n# Not every profile is an agent:\n# [profile.api]\n# command = [\"just\", \"dev\"]\n\n# [profile.api.env]\n# PORT = \"8001\"\n\n# [worktree] controls \"ais -w\" and \"ais wt\". Every worktree a session makes\n# lands under base/<session name>, on a branch named after the session, so one\n# session's work is one directory however many repos it touches.\n[worktree]\n# base = \"~/wt\"       # where session directories live\n# copy = [\".env\", \".claude/settings.local.json\"]\n                      # paths copied from the main checkout into each new\n                      # worktree, when the checkout has them\n# fetch = true        # \"git fetch origin\" before branching; false to work offline\n# auto = false        # give every session a worktree of its own, as if -w were\n                      # passed — but only when you are in a git repo; outside\n                      # one the session just runs where you are. --no-worktree\n                      # opts a single run out.\n\n# [tmux] controls what a session does to the pane it runs in. Whatever this\n# says, a session marks its pane with @ais_id, @ais_profile, @ais_desc and @cwd\n# for as long as it runs, so tmux (and tsm) can tell which pane is which.\n[tmux]\n# rename = true       # name the window after the session while it runs, and put\n                      # the old name back afterwards; false leaves tmux's own\n                      # naming alone (which calls every ais window \"Python\")\n\n# [notify] controls what \"ais notify\" does.\n[notify]\n# sound = \"Glass\"     # macOS notification sound; \"\" for silent\n# window = 60         # minutes a notification stays \"recent\" in ls/status/select\n# when_visible = \"skip\"  # or \"send\": notify even while you are looking at the pane\n# seen_after = 3      # seconds a pane must stay on screen before its call\n                      # counts as seen, and stops being marked as waiting\n# sink = [\"tsm\", \"notify\", \"--stdin\"]\n                      # offered every notification first, as JSON on stdin; it\n                      # answers {\"result\": \"shown\"|\"suppressed\"} or declines by\n                      # exiting non-zero. On a server, \"tsm notify\" passes it\n                      # to the laptop connected through \"tsm relay\".\n"

const claudeSessionConfig = "\n# Added by \"ais install --harness claude\": how claude names conversations, so\n# \"ais restart\" can pick one up again.\n[profile.claude.session]\nid = \"uuid4\"\nnew = [\"--session-id\", \"{id}\"]\nresume = [\"--resume\", \"{id}\"]\nfork = [\"--resume\", \"{id}\", \"--fork-session\"]\nconflicts = [\"-c\", \"--continue\", \"--fork-session\"]\n"

const piSessionConfig = "\n# Added by \"ais install --harness pi\": how pi names conversations, so \"ais\n# restart\" can pick one up again. pi's --session-id opens the session with that\n# id and creates one when there is none, so a single flag serves both.\n[profile.pi.session]\nid = \"uuid4\"\nnew = [\"--session-id\", \"{id}\"]\nresume = [\"--session-id\", \"{id}\"]\nconflicts = [\"-c\", \"--continue\", \"-r\", \"--resume\", \"--session\", \"--fork\", \"--no-session\"]\n"

const instructionsText = "## Notifications\n\n{notify_lead}\n\n```\nais notify \"the deps sweep finished; 3 tests still failing\"\n```\n\nALWAYS send one when you stop needing to do work and start needing me:\n\n- you are asking a question and cannot proceed until I answer\n- you hit a permission prompt, a login, or anything else only I can do\n- a long-running job/task finished, whether it passed or failed\n- you are done with the task and handing it back\n\nOne notification per stop, at the moment you stop — not before, not batched up\nlater. Say what happened and what you need, in one line, not \"task complete\".\n\nDo not manage the details yourself:\n\n- No `osascript`. `ais notify` picks the backend for the platform.\n- No session tag in the message. It titles the banner with the session\n  description, so I can tell parallel sessions apart already.\n- No checking whether I am looking. It skips the banner when this session's own\n  tmux pane is the one on screen, and records the notification either way. Pass\n  `-f` only if I must see the banner regardless.\n\nOutside an ais session it still notifies, just without a session tag, so calling\nit unconditionally is safe.\n\nI read them back with `ais status`, and sessions that notified recently sort to\nthe top of `ais select`.\n\n## AI sessions (ais)\n\n`ais` (`ais --help`) starts an agent harness with the right flags and env,\nrecords the run in `~/.ais/sessions.json`, and can jump back to its tmux pane\nlater. When `$AIS_SESSION` is set you are running inside one:\n\n- `$AIS_SESSION` — the 10-char ais id, e.g. `vw86nyuhe6`\n- `$AIS_SESSION_DESCRIPTION` — what I said the session is for (may be unset)\n- `$AIS_HARNESS` — the harness name, normally `{harness}`\n\nUse these opportunistically, never require them: outside ais they are all unset\nand every rule here just falls back to asking me.\n\n`ais name` prints the session's base name — use it for worktrees, branches, and\nanything else that needs to identify this work:\n\n```\nais name            # -> build-cli-tool-stock   (empty + exit 1 outside ais)\nais name --set foo  # only when I ask for a different name\n```\n\nDo not derive that name yourself. ais derives it from the description once and\nremembers it, so it stays the same across repos and however often you ask; a\nname you invent per call would not. If I ask for a different name, set it with\n`--set` rather than just using it, so the next call agrees with you.\n\n## Worktrees\n\nSessions I start with `ais -w` work in their own git worktree, so parallel\nsessions never fight over one checkout. When `$AIS_WORKTREE` is set, that is\nwhere you already are, on a branch named after the session.\n\nEvery worktree this session makes lives beside that one, under\n`$AIS_WORKTREE_BASE`. If the work reaches a second repository, do not clone it\nand do not run `git worktree` yourself — ais knows where this session's\ndirectory is and you do not:\n\n```\nais wt add ~/git/other-repo   # makes it; prints the path, and only the path\nais wt ls                     # this session's worktrees, with branch and state\nais wt path other-repo        # the path again, for cd\n```\n\n`cd \"$(ais wt add ~/git/other-repo)\"` is the whole idiom. Make as many as the\nwork needs; they all end up in one directory, on one branch name, so what this\nsession touched stays together.\n\nCommit often — after each coherent step, not once at the end. A worktree is\nyours alone, so there is no one to disturb by committing early, and a commit is\nthe only form the work survives in: if the session dies, `ais restart` gives you\nthe branch back and nothing else. Small commits with real messages, please, not\none \"wip\" at the end. Push when the work is ready for me, or when I ask.\n\nCommitted and pushed work is also what lets ais tidy up: `ais prune` eventually\nremoves the worktrees of long-dead sessions, but never one holding uncommitted\nchanges or unpushed commits.\n\nInteracting with ais:\n\n- `ais ls`, `ais ls -a`, `ais status`, `ais current` and `ais name` are\n  read-only as far as my work is concerned. Run them freely when I ask what is\n  running or which session is which.\n- NEVER run `ais select`. It switches my tmux client to another session's pane,\n  yanking my view away from wherever I am. That command is mine.\n- NEVER start a session yourself — no `ais run`, no `ais -- {harness}` (that\n  nests a harness inside this one), no `ais run --fork`, and no launching an\n  agent harness directly.\n- NEVER run `ais restart`. It takes over the pane it runs in and puts another\n  agent back to work; deciding that is mine.\n- `ais wt add`, `ais wt ls` and `ais wt path` are yours to run whenever the\n  work needs another repo. `ais prune` is not: it retires sessions and their\n  finished worktrees, and that is my call.\n- `~/.ais/sessions.json` belongs to ais, which locks it while writing. Never\n  hand-edit it, and never clean up your own session entry: ais marks the session\n  dead with its exit code when you terminate. `~/.ais/config.toml` is fine to\n  edit when I ask.\n"

const piExtensionText = "// {marker} — \"ais install --harness pi\" writes and rewrites this file.\n//\n// Tells ais which pi session this pane is in, so \"ais restart\" can reopen it,\n// and when you last sent it a prompt.\n// session_start fires on startup and again on /new, /resume, /fork and /clone —\n// every moment the session id changes under a running pi.\n//\n// Nothing in here may throw. pi lets an extension's exception reach the top and\n// dies on it, and losing the session you are working in is a far worse outcome\n// than losing the id ais wanted to write down — hence the catch-all, and hence\n// the error listener, without which node turns a missing ais into a crash.\n// detached, so that a pi exiting a moment later does not take the child with it.\nimport { spawn } from \"node:child_process\";\nimport type { ExtensionAPI } from \"@earendil-works/pi-coding-agent\";\n\nexport default function (pi: ExtensionAPI) {\n  pi.on(\"session_start\", (_event, ctx) => {\n    try {\n      if (!process.env.AIS_SESSION) return;  // a pi that ais did not start\n      const id = ctx.sessionManager?.getSessionId?.();\n      if (!id) return;                       // ephemeral: nothing to reopen later\n      const child = spawn({ais}, [\"_session-seen\", id], {\n        stdio: \"ignore\",\n        detached: true,\n      });\n      child.on(\"error\", () => {});\n      child.unref();\n    } catch {\n      // ais is not reachable from here; the session still runs fine without it.\n    }\n  });\n\n  // Every prompt you send: how long a session has been waiting for you is\n  // measured from the last one. Returns nothing, so the input goes on as is.\n  pi.on(\"input\", (event, _ctx) => {\n    try {\n      if (!process.env.AIS_SESSION) return;\n      const text = typeof event?.text === \"string\" ? event.text : \"\";\n      const child = spawn({ais}, [\"_activity\", \"--text\", text], {\n        stdio: \"ignore\",\n        detached: true,\n      });\n      child.on(\"error\", () => {});\n      child.unref();\n    } catch {\n      // as above\n    }\n  });\n}\n"

var notifyLead = map[string]string{
	"claude": "`ais notify` is how you get my attention. Use it instead of the built-in\nnotification tool, which suppresses itself whenever tmux/the terminal looks\nactive — which for me is always:",
	"pi":     "`ais notify` is how you get my attention:",
}

